class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        bits = [1] * n  # bitset of achievable sums for each index

        def ok(bs):
            for i in range(n):
                if not (bs[i] >> nums[i]) & 1:
                    return False
            return True

        if ok(bits):
            return 0
        for k, (l, r, v) in enumerate(queries):
            for i in range(l, r + 1):
                bits[i] |= bits[i] << v
            if ok(bits):
                return k + 1
        return -1
