class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        q = len(queries)

        def feasible(k):
            bits = [1] * n
            for i in range(k):
                l, r, v = queries[i]
                for j in range(l, r + 1):
                    bits[j] |= bits[j] << v
            for j in range(n):
                if not (bits[j] >> nums[j]) & 1:
                    return False
            return True

        if not feasible(q):
            return -1
        lo, hi = 0, q
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

